<script setup lang="ts">
import { computed } from "vue";
import { Icon } from "@iconify/vue";
import type { Column, DesignerTab, Index, ForeignKey, CheckConstraint, TableSpec } from "../types";
const props = defineProps<{ tab: DesignerTab }>();
const emit = defineEmits<{ update: [patch: Partial<TableSpec>]; pane: [pane: DesignerTab["pane"]]; preview: []; apply: [] }>();
function replaceColumn(values: string[], previous: string, next: string) { return values.map(value => value === previous ? next : value); }
function escapeRegex(value: string) { return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"); }
function setColumn(index: number, patch: Partial<Column>) {
  const spec = props.tab.spec!;
  const current = spec.columns[index];
  const nextName = typeof patch.name === "string" ? patch.name.trim() : current.name;
  if (nextName && nextName !== current.name) {
    const pattern = new RegExp(`\\b${escapeRegex(current.name)}\\b`, "g");
    emit("update", {
      columns: spec.columns.map((column, row) => row === index ? { ...column, ...patch, name: nextName } : column),
      primary_key: replaceColumn(spec.primary_key, current.name, nextName),
      indexes: spec.indexes.map(item => ({ ...item, columns: replaceColumn(item.columns, current.name, nextName) })),
      foreign_keys: spec.foreign_keys.map(item => ({
        ...item,
        columns: replaceColumn(item.columns, current.name, nextName),
        referenced_columns: item.referenced_table === spec.table && (!item.referenced_schema || item.referenced_schema === spec.schema)
          ? replaceColumn(item.referenced_columns, current.name, nextName)
          : item.referenced_columns,
      })),
      checks: spec.checks.map(item => ({ ...item, clause: item.clause.replace(pattern, nextName) })),
    });
    return;
  }
  emit("update", { columns: spec.columns.map((column, row) => row === index ? { ...column, ...patch } : column) });
}
function addColumn() { const columns = props.tab.spec!.columns; emit("update", { columns: [...columns, { name: `field_${columns.length + 1}`, data_type: "VARCHAR(255)", nullable: true, default: null, extra: "", comment: "", generation: "" }] }); }
function removeColumn(index: number) { emit("update", { columns: props.tab.spec!.columns.filter((_, row) => row !== index) }); }
function setPrimary(name: string, checked: boolean) { const keys = props.tab.spec!.primary_key; emit("update", { primary_key: checked ? [...new Set([...keys, name])] : keys.filter(key => key !== name) }); }
function setIndex(index: number, patch: Partial<Index>) { emit("update", { indexes: props.tab.spec!.indexes.map((item, row) => row === index ? { ...item, ...patch } : item) }); }
function setForeign(index: number, patch: Partial<ForeignKey>) { emit("update", { foreign_keys: props.tab.spec!.foreign_keys.map((item, row) => row === index ? { ...item, ...patch } : item) }); }
function setCheck(index: number, patch: Partial<CheckConstraint>) { emit("update", { checks: props.tab.spec!.checks.map((item, row) => row === index ? { ...item, ...patch } : item) }); }
function indexTypes() { return props.tab.spec?.engine === "PostgreSQL" ? ["BTREE", "HASH", "GIN", "GIST", "BRIN"] : ["BTREE", "HASH", "FULLTEXT"]; }
const tableWidth = computed(()=>props.tab.pane==='columns'?1456:props.tab.pane==='indexes'?904:props.tab.pane==='foreign'?(props.tab.spec?.engine==='PostgreSQL'?1424:1244):904);
const panes = [{ id: "columns", label: "字段", icon: "lucide:columns-3" }, { id: "indexes", label: "索引", icon: "lucide:list-tree" }, { id: "foreign", label: "外键", icon: "lucide:link-2" }, { id: "checks", label: "约束", icon: "lucide:badge-check" }, { id: "ddl", label: "DDL 预览", icon: "lucide:file-code-2" }] as const;
</script>

<template>
  <section v-if="tab.spec" class="designer-view">
    <header class="view-header"><div><Icon icon="lucide:panel-top-open" /><span><strong :title="tab.title">{{ tab.title }}</strong><small>{{ tab.database }}{{ tab.schema ? ` · ${tab.schema}` : '' }}</small></span></div><div class="form-field table-name">表名<WorkbenchInput aria-label="表名" :value="tab.spec.table" @input="emit('update', { table: ($event.target as HTMLInputElement).value })" /></div><a-button type="text" @click="emit('preview')"><Icon icon="lucide:file-scan" />生成 DDL</a-button><a-button type="primary" class="primary" :disabled="!tab.statements.length" @click="emit('apply')"><Icon icon="lucide:save" />保存</a-button></header>
    <WorkbenchTabs class="designer-tabs component-tabs" :active-key="tab.pane" @change="emit('pane',$event as DesignerTab['pane'])"><a-tab-pane v-for="pane in panes" :key="pane.id"><template #title><Icon :icon="pane.icon" /> {{ pane.label }}<a-badge v-if="pane.id==='columns'" :count="tab.spec.columns.length" /></template></a-tab-pane></WorkbenchTabs>
    <div v-if="tab.error" class="inline-error">{{ tab.error }}</div>
    <div v-if="tab.pane === 'columns'" class="designer-pane">
      <div class="designer-actions"><a-button type="text" @click="addColumn"><Icon icon="lucide:plus" />添加字段</a-button><span>双击或直接修改单元格内容</span></div><div class="structure-table">
        <a-table :data="tab.spec.columns" :pagination="false" :bordered="{cell:true}" size="small" :scroll="{x:tableWidth}" column-resizable><template #columns><a-table-column title="#" data-index="_row" :width="48"><template #cell="{rowIndex:index}">{{ index + 1 }}</template></a-table-column><a-table-column title="字段名" data-index="name" :width="180"><template #cell="{record:column,rowIndex:index}"><WorkbenchInput :aria-label="'字段名 第 '+(index+1)+' 行'" :value="column.name" @change="setColumn(index,{name:($event.target as HTMLInputElement).value})" /></template></a-table-column><a-table-column title="类型" data-index="data_type" :width="180"><template #cell="{record:column,rowIndex:index}"><WorkbenchInput :aria-label="'类型 第 '+(index+1)+' 行'" :value="column.data_type" @input="setColumn(index,{data_type:($event.target as HTMLInputElement).value})" /></template></a-table-column><a-table-column title="NULL" data-index="nullable" :width="72"><template #cell="{record:column,rowIndex:index}"><WorkbenchCheckbox :aria-label="'NULL 第 '+(index+1)+' 行'" :checked="column.nullable" @change="setColumn(index,{nullable:($event.target as HTMLInputElement).checked})" /></template></a-table-column><a-table-column title="主键" data-index="primary_key" :width="72"><template #cell="{record:column,rowIndex:index}"><WorkbenchCheckbox :aria-label="'主键 第 '+(index+1)+' 行'" :checked="tab.spec.primary_key.includes(column.name)" @change="setPrimary(column.name,($event.target as HTMLInputElement).checked)" /></template></a-table-column><a-table-column title="默认值" data-index="default" :width="160"><template #cell="{record:column,rowIndex:index}"><WorkbenchInput :aria-label="'默认值 第 '+(index+1)+' 行'" :value="String(column.default ?? '')" @input="setColumn(index,{default:($event.target as HTMLInputElement).value || null})" /></template></a-table-column><a-table-column title="额外" data-index="extra" :width="180"><template #cell="{record:column,rowIndex:index}"><WorkbenchInput :aria-label="'额外 第 '+(index+1)+' 行'" :value="column.extra" @input="setColumn(index,{extra:($event.target as HTMLInputElement).value})" /></template></a-table-column><a-table-column title="生成表达式" data-index="generation" :width="240"><template #cell="{record:column,rowIndex:index}"><WorkbenchInput :aria-label="'生成表达式 第 '+(index+1)+' 行'" :value="column.generation || ''" @input="setColumn(index,{generation:($event.target as HTMLInputElement).value})" /></template></a-table-column><a-table-column title="注释" data-index="comment" :width="260"><template #cell="{record:column,rowIndex:index}"><WorkbenchInput :aria-label="'注释 第 '+(index+1)+' 行'" :value="column.comment" @input="setColumn(index,{comment:($event.target as HTMLInputElement).value})" /></template></a-table-column><a-table-column title="操作" data-index="_actions" :width="64"><template #cell="{rowIndex:index}"><IconButton status="danger" label="删除" class="icon-danger" @click="removeColumn(index)"><Icon icon="lucide:trash-2" /></IconButton></template></a-table-column></template></a-table>
      </div>
    </div>
    <div v-if="tab.pane === 'indexes'" class="designer-pane"><div class="designer-actions"><a-button type="text" @click="emit('update',{indexes:[...tab.spec.indexes,{name:`idx_${tab.spec.indexes.length+1}`,unique:false,type:'BTREE',columns:[]}]})"><Icon icon="lucide:plus" />添加索引</a-button></div><div class="structure-table compact"><a-table :data="tab.spec.indexes" :pagination="false" :bordered="{cell:true}" size="small" :scroll="{x:tableWidth}" column-resizable><template #columns><a-table-column title="#" data-index="_row" :width="48"><template #cell="{rowIndex:index}">{{ index+1 }}</template></a-table-column><a-table-column title="名称" data-index="name" :width="220"><template #cell="{record:item,rowIndex:index}"><WorkbenchInput :aria-label="'名称 第 '+(index+1)+' 行'" :value="item.name" @input="setIndex(index,{name:($event.target as HTMLInputElement).value})" /></template></a-table-column><a-table-column title="唯一" data-index="unique" :width="72"><template #cell="{record:item,rowIndex:index}"><WorkbenchCheckbox :aria-label="'唯一 第 '+(index+1)+' 行'" :checked="item.unique" @change="setIndex(index,{unique:($event.target as HTMLInputElement).checked})" /></template></a-table-column><a-table-column title="类型" data-index="data_type" :width="180"><template #cell="{record:item,rowIndex:index}"><WorkbenchSelect aria-label="选择选项" :value="(item.type||'BTREE').toUpperCase()" @change="setIndex(index,{type:($event.target as HTMLSelectElement).value})"><a-option v-for="type in indexTypes()" :key="type" :value="type">{{ type }}</a-option></WorkbenchSelect></template></a-table-column><a-table-column title="字段（逗号分隔）" data-index="columns" :width="320"><template #cell="{record:item,rowIndex:index}"><WorkbenchInput :aria-label="'字段（逗号分隔） 第 '+(index+1)+' 行'" :value="item.columns.join(', ')" @input="setIndex(index,{columns:($event.target as HTMLInputElement).value.split(',').map(v=>v.trim()).filter(Boolean)})" /></template></a-table-column><a-table-column title="操作" data-index="_actions" :width="64"><template #cell="{rowIndex:index}"><IconButton status="danger" label="删除" class="icon-danger" @click="emit('update',{indexes:tab.spec.indexes.filter((_,row)=>row!==index)})"><Icon icon="lucide:trash-2" /></IconButton></template></a-table-column></template></a-table></div></div>
    <div v-if="tab.pane === 'foreign'" class="designer-pane"><div class="designer-actions"><a-button type="text" @click="emit('update',{foreign_keys:[...tab.spec.foreign_keys,{name:`fk_${tab.spec.foreign_keys.length+1}`,columns:[],referenced_schema:tab.spec.engine==='PostgreSQL'?tab.schema:'',referenced_table:'',referenced_columns:[],on_delete:'RESTRICT',on_update:'RESTRICT'}]})"><Icon icon="lucide:plus" />添加外键</a-button></div><div class="structure-table compact"><a-table :data="tab.spec.foreign_keys" :pagination="false" :bordered="{cell:true}" size="small" :scroll="{x:tableWidth}" column-resizable><template #columns><a-table-column title="名称" data-index="name" :width="220"><template #cell="{record:item,rowIndex:index}"><WorkbenchInput :aria-label="'名称 第 '+(index+1)+' 行'" :value="item.name" @input="setForeign(index,{name:($event.target as HTMLInputElement).value})" /></template></a-table-column><a-table-column title="本表字段" data-index="columns" :width="220"><template #cell="{record:item,rowIndex:index}"><WorkbenchInput :aria-label="'本表字段 第 '+(index+1)+' 行'" :value="item.columns.join(',')" @input="setForeign(index,{columns:($event.target as HTMLInputElement).value.split(',').map(v=>v.trim()).filter(Boolean)})" /></template></a-table-column><a-table-column v-if="tab.spec.engine==='PostgreSQL'" title="引用 Schema" data-index="referenced_schema" :width="180"><template #cell="{record:item,rowIndex:index}"><WorkbenchInput :aria-label="'引用 Schema 第 '+(index+1)+' 行'" :value="item.referenced_schema || tab.schema" @input="setForeign(index,{referenced_schema:($event.target as HTMLInputElement).value})" /></template></a-table-column><a-table-column title="引用表" data-index="referenced_table" :width="200"><template #cell="{record:item,rowIndex:index}"><WorkbenchInput :aria-label="'引用表 第 '+(index+1)+' 行'" :value="item.referenced_table" @input="setForeign(index,{referenced_table:($event.target as HTMLInputElement).value})" /></template></a-table-column><a-table-column title="引用字段" data-index="referenced_columns" :width="220"><template #cell="{record:item,rowIndex:index}"><WorkbenchInput :aria-label="'引用字段 第 '+(index+1)+' 行'" :value="item.referenced_columns.join(',')" @input="setForeign(index,{referenced_columns:($event.target as HTMLInputElement).value.split(',').map(v=>v.trim()).filter(Boolean)})" /></template></a-table-column><a-table-column title="ON DELETE" data-index="on_delete" :width="160"><template #cell="{record:item,rowIndex:index}"><WorkbenchSelect aria-label="选择选项" :value="item.on_delete" @change="setForeign(index,{on_delete:($event.target as HTMLSelectElement).value})"><a-option value="RESTRICT">RESTRICT</a-option><a-option value="CASCADE">CASCADE</a-option><a-option value="SET NULL">SET NULL</a-option><a-option value="NO ACTION">NO ACTION</a-option></WorkbenchSelect></template></a-table-column><a-table-column title="ON UPDATE" data-index="on_update" :width="160"><template #cell="{record:item,rowIndex:index}"><WorkbenchSelect aria-label="选择选项" :value="item.on_update" @change="setForeign(index,{on_update:($event.target as HTMLSelectElement).value})"><a-option value="RESTRICT">RESTRICT</a-option><a-option value="CASCADE">CASCADE</a-option><a-option value="SET NULL">SET NULL</a-option><a-option value="NO ACTION">NO ACTION</a-option></WorkbenchSelect></template></a-table-column><a-table-column title="操作" data-index="_actions" :width="64"><template #cell="{rowIndex:index}"><IconButton status="danger" label="删除" class="icon-danger" @click="emit('update',{foreign_keys:tab.spec.foreign_keys.filter((_,row)=>row!==index)})"><Icon icon="lucide:trash-2" /></IconButton></template></a-table-column></template></a-table></div></div>
    <div v-if="tab.pane === 'checks'" class="designer-pane"><div class="designer-actions"><a-button type="text" @click="emit('update',{checks:[...tab.spec.checks,{name:`chk_${tab.spec.checks.length+1}`,clause:''}]})"><Icon icon="lucide:plus" />添加 CHECK</a-button></div><div class="structure-table compact"><a-table :data="tab.spec.checks" :pagination="false" :bordered="{cell:true}" size="small" :scroll="{x:tableWidth}" column-resizable><template #columns><a-table-column title="名称" data-index="name" :width="220"><template #cell="{record:item,rowIndex:index}"><WorkbenchInput :aria-label="'名称 第 '+(index+1)+' 行'" :value="item.name" @input="setCheck(index,{name:($event.target as HTMLInputElement).value})" /></template></a-table-column><a-table-column title="检查表达式" data-index="clause" :width="620"><template #cell="{record:item,rowIndex:index}"><WorkbenchInput :aria-label="'检查表达式 第 '+(index+1)+' 行'" :value="item.clause" placeholder="amount >= 0" @input="setCheck(index,{clause:($event.target as HTMLInputElement).value})" /></template></a-table-column><a-table-column title="操作" data-index="_actions" :width="64"><template #cell="{rowIndex:index}"><IconButton status="danger" label="删除" class="icon-danger" @click="emit('update',{checks:tab.spec.checks.filter((_,row)=>row!==index)})"><Icon icon="lucide:trash-2" /></IconButton></template></a-table-column></template></a-table></div></div>
    <div v-if="tab.pane === 'ddl'" class="ddl-pane"><div v-if="tab.dangerous.length" class="danger-banner"><Icon icon="lucide:triangle-alert" /><span><b>检测到危险操作</b><small>{{ tab.dangerous.length }} 条语句可能删除或重建结构</small></span></div><template v-if="tab.statements.length"><div v-for="(statement,index) in tab.statements" :key="index" class="ddl-block"><header>语句 {{ index+1 }}<span v-if="tab.dangerous.includes(statement)">危险</span></header><pre>{{ statement }};</pre></div></template><div v-else class="empty-ddl"><Icon icon="lucide:file-code-2" /><b>尚未生成 DDL</b><p>修改结构后点击“生成 DDL”。</p></div></div>
    <footer class="table-options"><template v-if="tab.spec.engine==='PostgreSQL'"><div class="form-field">引擎<WorkbenchInput aria-label="引擎" value="PostgreSQL" disabled /></div><div class="form-field">字符集<WorkbenchInput aria-label="字符集" value="UTF8" disabled /></div><div class="form-field">Schema<WorkbenchInput aria-label="Schema" :value="tab.spec.schema" disabled /></div></template><template v-else><div class="form-field">引擎<WorkbenchSelect aria-label="选择选项" :value="tab.spec.engine" @change="emit('update',{engine:($event.target as HTMLSelectElement).value})"><a-option value="InnoDB">InnoDB</a-option><a-option value="MyISAM">MyISAM</a-option><a-option value="MEMORY">MEMORY</a-option></WorkbenchSelect></div><div class="form-field">字符集<WorkbenchSelect aria-label="选择选项" :value="tab.spec.charset" @change="emit('update',{charset:($event.target as HTMLSelectElement).value})"><a-option value="utf8mb4">utf8mb4</a-option><a-option value="utf8">utf8</a-option><a-option value="latin1">latin1</a-option></WorkbenchSelect></div><div class="form-field">排序规则<WorkbenchInput aria-label="排序规则" :value="tab.spec.collation" @input="emit('update',{collation:($event.target as HTMLInputElement).value})" /></div></template><div class="form-field grow">表注释<WorkbenchInput aria-label="表注释" :value="tab.spec.comment" @input="emit('update',{comment:($event.target as HTMLInputElement).value})" /></div></footer>
  </section>
</template>
